async function probe(id, depth) {
  const n = await figma.getNodeByIdAsync(id);
  const out = { id, name: n.name, type: n.type, w: Math.round(n.width), h: Math.round(n.height) };
  if ("fills" in n && n.fills !== figma.mixed && Array.isArray(n.fills) && n.fills.length) {
    const f = n.fills[0];
    out.fill = { type: f.type, scaleMode: f.scaleMode, visible: f.visible };
    if (f.type === "SOLID") out.fill.color = f.color;
  }
  if ("strokes" in n && Array.isArray(n.strokes) && n.strokes.length) out.hasStroke = true;
  if (depth > 0 && "children" in n) out.children = [];
  if (depth > 0 && "children" in n) {
    for (const c of n.children) {
      const cp = { id: c.id, name: c.name, type: c.type, w: Math.round(c.width), h: Math.round(c.height) };
      if ("constraints" in c) cp.constraints = c.constraints.horizontal + "/" + c.constraints.vertical;
      if ("fills" in c && Array.isArray(c.fills) && c.fills.length && c.fills[0].type === "SOLID") cp.fill = c.fills[0].color;
      if ("strokes" in c && Array.isArray(c.strokes) && c.strokes.length) cp.stroke = true;
      out.children.push(cp);
    }
  }
  return out;
}
